function getDailyStats() {
  const days = [];
  const now = Date.now();
  for (let i = 13; i >= 0; i--) {
    const d = new Date(now - i * 86400000).toISOString().slice(0, 10);
    days.push({ day: d, clips: (i === 0 ? 3 : 0), posted: 0, views: 0 });
  }
  return days;
}

